root=pathlib.Path.cwd()
with tempfile.TemporaryDirectory(prefix='b07r2-review-') as tmp:
    base=pathlib.Path(tmp)
    for module in ('pose-mcp','mcp-enforce'):
        shutil.copytree(root/module,base/module,ignore=shutil.ignore_patterns('.git','node_modules','*.test'))
    for pkg,source in SOURCES.items():
        (base/'pose-mcp/internal'/pkg/'b07r2_review_test.go').write_text(source)
    result=subprocess.run(['go','test','./internal/pose','./internal/cli','-run','^TestB07R2','-count=1','-v'],cwd=base/'pose-mcp')
    raise SystemExit(result.returncode)
